//###########################################################
retrieveMissingSymbolData = async function() {
  var retrieveMissingData;
  log("retrieveMissingSymbolData");
  retrieveMissingData = async function(symbol) {
    var err;
    if (symbolToData[symbol] != null) {
      return;
    }
    try {
      symbolToData[symbol] = (await dCache.getHistoryHLC(symbol, 31));
    } catch (error) {
      err = error;
      console.error(err);
    }
  };
  await Promise.all(relevantPairs.map(retrieveMissingData));
  log("retrieved missingForexSymbols");
};

//###########################################################
generateScreeningResult = async function(relevantPairs) {
  var err;
  log("generateScreeningResult");
  // guarding from multiple simultaneous runs 
  if (isProcessing && processOnceMore) {
    return;
  }
  if (isProcessing) {
    return processOnceMore = true;
  }
  isProcessing = true;
  try {
    await retrieveMissingSymbolData();
  } catch (error) {
    err = error;
    log(err);
  }
  try {
    await resultTable.screenAndRender(relevantPairs, symbolToData);
  } catch (error) {
    err = error;
    log(err);
  }
  isProcessing = false;
  if (processOnceMore) {
    processOnceMore = false;
    generateScreeningResult(relevantPairs);
  }
};
